SELECT 


    a.plan_id = #{planId}
    AND a.status = #{status}
    AND a.dept_id = #{deptId}
    AND a.reviewer_id = #{reviewerId}
    AND a.employee_id = #{employeeId}

        AND (e.emp_no LIKE CONCAT('%', #{keyword}, '%') OR e.name LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY a.plan_id DESC, e.emp_no
